package org.example.insurance.premium;
import java.math.BigDecimal; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/payments") public class PremiumController { private final PaymentRepository payments; private final RestClient policies; PremiumController(PaymentRepository payments,@Value("${clients.policy-url}") String url){this.payments=payments;policies=RestClient.create(url);}@PostMapping public ResponseEntity<PremiumPayment> record(@RequestBody PremiumPayment payment){Map<?,?> policy=policies.get().uri("/policies/{id}",payment.getPolicyId()).retrieve().body(Map.class);if(!"ACTIVE".equals(policy.get("policyStatus")))return ResponseEntity.unprocessableEntity().build();return ResponseEntity.status(201).body(payments.save(payment));}@GetMapping("/policy/{id}") public List<PremiumPayment> byPolicy(@PathVariable Long id){return payments.findByPolicyId(id);}@GetMapping("/policy/{id}/summary") public Map<String,Object> summary(@PathVariable Long id){BigDecimal total=payments.findByPolicyId(id).stream().filter(p->"SUCCESS".equals(p.getPaymentStatus())).map(PremiumPayment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("policyId",id,"totalPremiumPaid",total);}}
